import { describe, expect, it } from "vitest";

import { verifyLegacyPassword } from "../../server/utils/password";

// Hash generated by @adonisjs/hash (the library the old nuxt-auth-utils setup
// used) for the password "legacytest123". Hard-coded so the test proves real
// interop instead of re-deriving with the same code it is testing.
const ADONIS_HASH =
  "$scrypt$n=16384,r=8,p=1$N7H0Rx6fwho62aqK1Mj7WQ$UnQLwnlim9J75hUyM3BQXxRkro7NWnBxQ0at85Vri+QbNDD0jB9mgblGG/1DIFyAzdi88d1cT7vo/SRuffnhJQ";

describe("verifyLegacyPassword", () => {
  it("accepts the password behind a real Adonis hash", async () => {
    await expect(
      verifyLegacyPassword(ADONIS_HASH, "legacytest123")
    ).resolves.toBe(true);
  });

  it("rejects a wrong password", async () => {
    await expect(verifyLegacyPassword(ADONIS_HASH, "wrong")).resolves.toBe(
      false
    );
  });

  it("rejects hashes that are not in the legacy format", async () => {
    await expect(
      verifyLegacyPassword("salt:deadbeef", "anything")
    ).resolves.toBe(false);
  });

  it("matches hashes whose base64 carries padding", async () => {
    // 16-byte salt and 64-byte key need `==` padding; the store may keep it.
    const [, scheme, params, saltPart, keyPart] = ADONIS_HASH.split("$");
    const padded = `$${scheme}$${params}$${saltPart}==$${keyPart}==`;
    await expect(verifyLegacyPassword(padded, "legacytest123")).resolves.toBe(
      true
    );
  });
});
